local lastFire = 0
local lastReason = nil
local function reason(text)
    if text ~= lastReason then
        log(S(49) .. text)
        lastReason = text
    end
end
function autoPlace.SetEnabled(state)
    if state == enabled then
        return
    end
    enabled = state
    lastReason = nil
    log(S(247) .. (enabled and S(13) or S(316)))
end
function autoPlace.IsEnabled()
    return enabled
end
function autoPlace.Step()
    if not enabled then
        return
    end
    local now = tick()
    if now - lastFire < FIRE_INTERVAL then
        return
    end
    lastFire = now
    local player = Players.LocalPlayer
    local character = player.Character
    local backpack = player:FindFirstChild(S(85))
    if not character or not backpack then
        reason(S(298))
        return
    end
    local humanoid = character:FindFirstChildOfClass(S(314))
    local tool = backpack:FindFirstChildWhichIsA(S(67))
    if not humanoid then
        reason(S(147))
        return
    end
    if not tool then
        reason(S(260))
        return
    end
    local plot = getCurrentPlot()
    if not plot then
        reason(S(245))
        return
    end
    local parts = getPlotParts(plot)
    if not parts.Holders then
        reason(S(16))
        return
    end
    local placed = false
    for _, holder in ipairs(parts.Holders:GetChildren()) do
        local prompt = findHolderPrompt(holder)
        if isHolderEmpty(prompt) then
            humanoid:EquipTool(tool)
            local ok, err = pcall(function()
                fireproximityprompt(prompt, Enum.ProximityPromptInputType.Keyboard, prompt.HoldDuration)
            end)
            if ok then
                log(S(142) .. tool.Name .. S(275) .. holder.Name)
            else
                log(S(86) .. tostring(err))
            end
            placed = true
            break
        end
    end
    if not placed then
        reason(S(181) .. #parts.Holders:GetChildren() .. S(12))
    else
        lastReason = nil
    end
end
return autoPlace
end
end
