end
local function countCards(sellFrame)
    local content = sellFrame:FindFirstChild(S(402))
    local scroll = content and content:FindFirstChild(S(311))
    if not scroll then
        return 0
    end
    local count = 0
    for _, child in ipairs(scroll:GetChildren()) do
        if child.Name == S(321) then
            count = count + 1
        end
    end
    return count
end
local function clickButton(button)
    local ok, err = click.Real(button)
    if not ok then
        log(S(112) .. button.Name .. S(390) .. tostring(err))
    end
    return ok
end
local function getSellStandPromptPart()
    local sellStand = Workspace:FindFirstChild(S(182))
    local prompt = sellStand and sellStand:FindFirstChildWhichIsA(S(42), true)
    return prompt, prompt and prompt.Parent
end
local autoSell = {}
local enabled = false
local busy = false
local lastAttempt = 0
function autoSell.SetEnabled(state)
    if state == enabled then
        return
    end
    enabled = state
    if not enabled then
        if not busy then
            teleport.Return()
        end
        log(S(421))
    else
        lastAttempt = 0
        log(S(294))
    end
end
function autoSell.IsEnabled()
    return enabled
end
local function runJob()
    busy = true
    local prompt, promptPart = getSellStandPromptPart()
    if not (prompt and promptPart) then
        busy = false
        return
    end
    teleport.To(promptPart)
    local ok, err = pcall(function()
        fireproximityprompt(prompt, Enum.ProximityPromptInputType.Keyboard, prompt.HoldDuration)
    end)
    if not ok then
        log(S(47) .. tostring(err))
        teleport.Return()
        busy = false
        return
    end
    task.wait(0.8)
    if not enabled then
        teleport.Return()
        busy = false
        return
    end
    local sellFrame = getSellFrame()
    if not (sellFrame and sellFrame.Visible) then
        log(S(33))
        teleport.Return()
        busy = false
        return
    end
    local cardCount = countCards(sellFrame)
    if cardCount == 0 then
        log(S(307))
        local closeButton = sellFrame:FindFirstChild(S(442))
        if closeButton then
            clickButton(closeButton)
        end
        teleport.Return()
        busy = false
        return
    end
    local content = sellFrame:FindFirstChild(S(31))
    local selectAllButton = content and content:FindFirstChild(S(256))
    local sellButton = content and content:FindFirstChild(S(117))
    if selectAllButton and labelText(selectAllButton) == S(198) then
        clickButton(selectAllButton)
        log(S(388) .. cardCount .. S(263))
    end
    local sawLabel = nil
    for _ = 1, 5 do
        task.wait(0.3)
        sawLabel = sellButton and labelText(sellButton) or nil
        if sawLabel and sawLabel:find(S(64), 1, true) then
            break
        end
    end
    if sawLabel and sawLabel:find(S(164), 1, true) then
        clickButton(sellButton)
        log(S(179))
    else
        log(S(109) .. tostring(sawLabel)
            .. S(106) .. (selectAllButton and labelText(selectAllButton) or S(136)) .. S(268))
    end
    task.wait(0.5)
    teleport.Return()
    busy = false
end
function autoSell.Step()
    if not enabled or busy then
        return
    end
    local now = tick()
    if now - lastAttempt < CHECK_INTERVAL then
        return
    end
    lastAttempt = now
    task.spawn(runJob)
end
return autoSell
end
end
