    indent = indent or S(250)
    for _, child in ipairs(instance:GetChildren()) do
        local line = indent .. child.ClassName .. S(45) .. child.Name .. S(281)
        if child:IsA(S(59)) then
            line = line .. string.format(
                S(173),
                child.ActionText, child.ObjectText, tostring(child.HoldDuration)
            )
        elseif child:IsA(S(101)) then
            line = line .. string.format(S(293), tostring(child.MaxActivationDistance))
        elseif child:IsA(S(56)) or child:IsA(S(73)) then
            line = line .. S(87)
        end
        log(line)
        for attrName, attrValue in pairs(child:GetAttributes()) do
            log(indent .. S(84) .. attrName .. S(371) .. tostring(attrValue))
        end
        dumpInstance(child, log, indent .. S(210))
    end
end
return dumpInstance
end
